\begin{tikzpicture}[every node/.style={font=\large}, scale=0.62]
\draw[->] (0,0)--(0,6.4); \draw[->] (0,0)--(11,0); \foreach \y/\lab in {1/25,2/50,3/75,4/100,5/125} {\draw (-0.15,\y)--(0,\y); \node[left,font=\scriptsize] at (-0.15,\y) {$\lab$};} \node[left,font=\scriptsize] at (-0.15,0) {$0$};
\draw (0.4,0) rectangle (1.6,3); \draw (2.4,0) rectangle (3.6,5); \draw (4.4,0)--(5.6,0); \draw (6.4,0) rectangle (7.6,2); \draw (8.4,0) rectangle (9.6,4); \foreach \x/\lab in {1/Repair,3/Advice,5/Legal,7/Housing,9/Health} {\node[below,font=\scriptsize] at (\x,0) {\lab};}
